head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.vScrenID = "ULDINS05500.xml";
scwin.V_ISUR_APPL_ID = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
/********************************************** 
 * 함수명   : ins_search
 * 설명       : 발행기관 신규 접수대상 조회한다.
 ***********************************************/
scwin.ins_search = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS05500_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.corpinfo.select.listCorpIssInstNewRctInquiry";
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_Grid); // 그리드명을 표기

};


/********************************************** 
 * 함수명   : readCorpInfoSimbol
 * 설명       : 심볼 중복검사 한다.
 ***********************************************/
scwin.readCorpInfoSimbol = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS05000_DETAIL_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.corpinfo.select.readCorpInfoSimbol" + "&{P}ISUR_CD=" + "" + "&{P}COM_SYMBL=" + txb_ISUR_SYMBL.getValue();

    // alert(url);
    dts_Simbol.DataID = encodeURI(url);
    dts_Simbol.reset();
};

/********************************************** 
 * 함수명   : ins_detail
 * 설명       : 발행기관 신규상세  조회한다.
 ***********************************************/
scwin.ins_detail = function() {
    //alert(V_ISUR_APPL_ID);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=ULDINS05500_DETAIL_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.corpinfo.select.readCorpIssInstNewRctView" + "&{P}param01=" + scwin.V_ISUR_APPL_ID;
    dts_detail.DataID = encodeURI(url);
    dts_detail.reset();
};


/********************************************** 
 * 함수명   : fn_GetParam
 * 설명       : 전달값을 정의한다.
 ***********************************************/
scwin.arrPar = new Array();
scwin.fn_GetParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue();
    scwin.arrPar[1] = txb_param2.getValue();
    scwin.arrPar[2] = txb_param3.getValue();

    //alert(arrPar[0] + " " + arrPar[1]);
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};

/********************************************** 
 * 함수명   : fn_Set_Detail
 * 설명       : 국가코드에 따른 설정을 정의한다.
 ***********************************************/
scwin.fn_Set_Detail = function(CNTR_ISO_CD) {
    //alert(CNTR_ISO_CD);
    // 국내법인이 아닌 경우 우편번호 팝업금지
    if (CNTR_ISO_CD == "410") {
        img_ZIPCD.src = "../img/btn_search.gif";
        img_ZIPCD.setDisabled(false);
        txb_CORP_REG_NO.setDisabled(false);
        txb_BZ_REG_NO.setDisabled(false);
    } else {
        img_ZIPCD.src = "../img/btn_search_d.gif";
        img_ZIPCD.setDisabled(true);
        txb_CORP_REG_NO.setDisabled(true);
        txb_BZ_REG_NO.setDisabled(true);
    }
    var CNTR_CD = CNTR_ISO_CD;
    if (CNTR_CD == "410") {
        txb_ADDR.setReadOnly(true);
        txb_ADDR.style.backgroundColor = '#b9d4f7';
        txb_ENG_ADDR.setReadOnly(true);
        txb_ENG_ADDR.style.backgroundColor = '#b9d4f7';
        //txb_DTL_ADDR.disabled = true; 
        //	txb_ADDR.background-color = '#b9d4f7';	

    } else {
        txb_ADDR.setReadOnly(false);
        txb_ADDR.style.backgroundColor = '#ffffff';
        txb_ENG_ADDR.setReadOnly(false);
        txb_ENG_ADDR.style.backgroundColor = '#ffffff';
        //txb_DTL_ADDR.disabled =  false; 

    }
};





/********************************************** 
 * 함수명   : ins_register
 * 설명       : 발행기관 신규 접수 등록한다.
 ***********************************************/
scwin.ins_register = function() {
    if (!$c.cp.isModified(dts_detail)) {
        dts_detail.setCellData(dts_detail.getRowPosition(), "STD_CD_MEMO", " ");
    }

    //textarea 개행문자제거
    txa_STD_CD_MEMO.text = txa_STD_CD_MEMO.text.replace(/[\r|\n]/g, "");
    if (txb_simbol_chk.getValue() == "F") {
        $c.win.alert("중복된 심볼입니다.");
        txb_ISUR_SYMBL.focus();
        return;
    }
    if (txb_ISUR_SYMBL.getValue() != "") {
        if (txb_simbol_chk.getValue() == "X") {
            $c.win.alert("심볼 중복체크 해주세요.");
            txb_ISUR_SYMBL.focus();
            return;
        }
    }

    //16.11.03 임시기관코드 삭제 후 처리
    /*
    if(txb_ISUR_CD.value !="" ) {
    	alert( "임시발행기관코드를 삭제하세요.");
    	txb_ISUR_CD.focus();
    	return;
    } */

    if (txb_COM_NM.getValue() == "" || txb_COM_NM.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행기관명"));
        txb_COM_NM.focus();
        return;
    }
    if (!$c.stf.checkMaxLength(txb_COM_NM, 80, "발행기관명")) {
        //txb_COM_NM.value = "";
        txb_COM_NM.focus();
        return false;
    }
    if (txb_COM_ABBRV.getValue() == "" || txb_COM_ABBRV.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행기관약명"));
        txb_COM_ABBRV.focus();
        return;
    }
    if (!$c.stf.checkMaxLength(txb_COM_ABBRV, 40, "발행기관약명")) {
        //txb_COM_ABBRV.value = "";
        txb_COM_ABBRV.focus();
        return false;
    }
    if (txb_COM_ENG_NM.getValue() == "" || txb_COM_ENG_NM.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행기관(EN)"));
        txb_COM_ENG_NM.focus();
        return;
    }
    if (!$c.stf.checkMaxLength(txb_COM_ENG_NM, 80, "발행기관(EN)")) {
        //txb_COM_ENG_NM.value = "";
        txb_COM_ENG_NM.focus();
        return false;
    }
    if (txb_COM_ENG_ABBRV.getValue() == "" || txb_COM_ENG_ABBRV.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행기관약명(EN)"));
        txb_COM_ENG_ABBRV.focus();
        return;
    }
    if (!$c.stf.checkMaxLength(txb_COM_ENG_ABBRV, 40, "발행기관약명(EN)")) {
        //txb_COM_ENG_ABBRV.value = "";
        txb_COM_ENG_ABBRV.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISUR_NM1, 80, "상호변경_상호1")) {
        //txb_COM_ENG_NM.value = "";
        txb_ISUR_NM1.focus();
        return false;
    }
    if (txb_ISUR_NM1.getValue() != "") {
        if (edt_CHG_APPL_DD1.getValue() == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "상호변경_변경일1"));
            edt_CHG_APPL_DD1.focus();
            return;
        }
    }
    if (!$c.stf.checkMaxLength(txb_ISUR_NM2, 80, "상호변경_상호2")) {
        //txb_COM_ENG_NM.value = "";
        txb_ISUR_NM2.focus();
        return false;
    }
    if (txb_ISUR_NM2.getValue() != "") {
        if (edt_CHG_APPL_DD2.getValue() == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "상호변경_변경일2"));
            edt_CHG_APPL_DD2.focus();
            return;
        }
    }
    if (!$c.stf.checkMaxLength(txb_HPAGE, 200, "홈페이지")) {
        //txb_COM_ENG_NM.value = "";
        txb_HPAGE.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_BZ_REG_IND_NM, 100, "업종")) {
        //txb_COM_ENG_NM.value = "";
        txb_BZ_REG_IND_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_BZ_REG_BZCOND_NM, 100, "업태")) {
        //txb_COM_ENG_NM.value = "";
        txb_BZ_REG_BZCOND_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_BFSPLIT_COM_NM, 100, "분할전법인명")) {
        //txb_COM_ENG_NM.value = "";
        txb_BFSPLIT_COM_NM.focus();
        return false;
    }
    if (txb_CNTR_ISO_CD.getValue() == "" || txb_CNTR_ISO_CD.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "국가코드"));
        txb_CNTR_ISO_CD.focus();
        return;
    }
    if ($c.stf.getObjectValue(edt_FOUND_DD) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "설립일"));
        edt_FOUND_DD.focus();
        return;
    }
    if (fn_CheckDateObj(edt_FOUND_DD, "설립일")) {
        return false;
    }
    if ($c.stf.getObjectValue(txb_CEO_NM) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "대표이사"));
        txb_CEO_NM.focus();
        return;
    }
    if (!$c.stf.checkMaxLength(txb_CEO_NM, 20, "대표이사")) {
        //txb_COM_ENG_NM.value = "";
        txb_CEO_NM.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_SPOT_ISU_TRD_MKT_TP_CD) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "시장구분"));
        cmb_SPOT_ISU_TRD_MKT_TP_CD.focus();
        return;
    }
    if ($c.stf.getObjectValue(cmb_COM_ATTR_TP_CD) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "회사속성"));
        cmb_COM_ATTR_TP_CD.focus();
        return;
    }
    if ($c.stf.getObjectValue(cmb_LIST_STAT_CD) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "상장여부"));
        cmb_LIST_STAT_CD.focus();
        return;
    }
    if (!$c.stf.checkMaxLength(txb_ADDR, 200, "주소")) {
        //txb_COM_ENG_NM.value = "";
        txb_ADDR.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_DTL_ADDR, 200, "상세주소")) {
        //txb_COM_ENG_NM.value = "";
        txb_DTL_ADDR.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ENG_ADDR, 200, "영문주소")) {
        txb_ENG_ADDR.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ENG_DTL_ADDR, 200, "영문상세주소")) {
        txb_ENG_DTL_ADDR.focus();
        return false;
    }

    /* 결산월 control */
    var cmb_ChkCnt = 0;
    var tmpCnt = 0;
    var tmpAcntMM = new Array();
    for (var i = 1; i <= 12; i++) {
        if (dts_detail.getCellData(dts_detail.getRowPosition(), "ACNTCLS_MMDD" + i) == "") {
            cmb_ChkCnt = cmb_ChkCnt + 1;
        }
    }
    if (cmb_ChkCnt == 12) {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "결산월"));
        cmb_ACNTCLS_MM1.focus();
        return;
    }
    for (var i = 1; i <= 12; i++) {
        for (var j = 12; j >= 1; j--) {
            if (i != j) {
                if (dts_detail.getCellData(dts_detail.getRowPosition(), "ACNTCLS_MMDD" + i) != "") {
                    if (dts_detail.getCellData(dts_detail.getRowPosition(), "ACNTCLS_MMDD" + j) != "") {
                        if (dts_detail.getCellData(dts_detail.getRowPosition(), "ACNTCLS_MMDD" + i) == dts_detail.getCellData(dts_detail.getRowPosition(), "ACNTCLS_MMDD" + j)) {
                            $c.win.alert("동일한 결산월이 존재합니다.\n결산월을 확인해주세요!");
                            return false;
                        }
                    }
                }
            } else {
                if (dts_detail.getCellData(dts_detail.getRowPosition(), "ACNTCLS_MMDD" + i) != "") {
                    tmpAcntMM[tmpCnt] = dts_detail.getCellData(dts_detail.getRowPosition(), "ACNTCLS_MMDD" + i);
                    tmpCnt = tmpCnt + 1;
                }
            }
        }
    }
    if (cmb_ChkCnt == 11) {
        for (var i = 2; i <= 12; i++) {
            if (dts_detail.getCellData(dts_detail.getRowPosition(), "ACNTCLS_MMDD" + i) != "") {
                dts_detail.setCellData(dts_detail.getRowPosition(), "ACNTCLS_MMDD1", dts_detail.getCellData(dts_detail.getRowPosition(), "ACNTCLS_MMDD" + i));
                dts_detail.setCellData(dts_detail.getRowPosition(), "ACNTCLS_MMDD" + i, "");
            }
        }
    } else {
        for (var h = 1; h <= 12; h++) {
            dts_detail.setCellData(dts_detail.getRowPosition(), "ACNTCLS_MMDD" + h, "");
        }
        for (var k = 1; k <= tmpCnt; k++) {
            dts_detail.setCellData(dts_detail.getRowPosition(), "ACNTCLS_MMDD" + k, tmpAcntMM[k - 1]);
        }
    }

    //발행기관명(한글), 발행기관명(한글약명), 주소상세 완성형한글 체크
    var urlck = "/CorpInfoAction.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=processCompleteKoreanCheck";
    urlck += "&outputMessageId=INS_CHECK_CLS_COMPLETE_KOREAN";
    urlck += "&COM_NM=" + $c.stf.getObjectValue(txb_COM_NM);
    urlck += "&COM_ABBRV=" + $c.stf.getObjectValue(txb_COM_ABBRV);
    urlck += "&DTL_ADDR=" + $c.stf.getObjectValue(txb_DTL_ADDR);
    urlck += "&CEO_NM=" + $c.stf.getObjectValue(txb_CEO_NM);
    urlck += "&BZ_REG_IND_NM=" + $c.stf.getObjectValue(txb_BZ_REG_IND_NM);
    urlck += "&BZ_REG_BZCOND_NM=" + $c.stf.getObjectValue(txb_BZ_REG_BZCOND_NM);
    dts_completeKorean.SyncLoad = "true";
    dts_completeKorean.DataID = encodeURI(urlck);
    dts_completeKorean.Reset();
    var msg = '';
    msg += ' 발행기관(한글명, 한글약명, 상세주소, 대표이사, 업종, 업태)';
    msg += '\n\n 한글표기에 문제가 있습니다. 계속 진행하시겠습니까?';
    msg += '\n\n (시스템담당자에게 문의하시기 바랍니다.)';
    if (dts_completeKorean.getTotalRow() > 0) {
        if (!window.confirm(msg)) {
            processGp = '1';
            return;
        }
    }
    if (!confirm("신규등록 하시겠습니까?")) {
        return;
    }
    txb_ISUR_CD.setValue(""); //16.11.03 임시기관코드 삭제 후 처리

    trs_save.Action = "/CorpInfoAction.do?method=registerCorpIssInstNewRct" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    trs_save.KeyName = "toinb_dataid4";
    trs_save.KeyValue = "JSP(O:pReturnOut=dts_Rst,I:pInput=dts_detail)";
    trs_save.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm + ",EMAIL=" + js_email;
    trs_save.Post();
};


/********************************************** 
 * 함수명   : ins_return
 * 설명       : 발행기관 반송 등록한다.
 ***********************************************/
scwin.ins_return = function() {

    //dts_return.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_return.insertRow();
    dts_return.setCellData(1, "ISUR_CD", $c.stf.getObjectValue(txb_ISUR_CD));
    dts_return.setCellData(1, "CNTR_CD", $c.stf.getObjectValue(txb_CNTR_ISO_CD));
    dts_return.setCellData(1, "ISUR_APPL_ID", $c.stf.getObjectValue(txb_ISUR_APPL_ID));
    trs_modify.Action = "/CorpInfoAction.do?method=returnCorpIssInstNewRct" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    trs_modify.KeyName = "toinb_dataid4";
    trs_modify.KeyValue = "JSP(O:pReturnOut=dts_Rst2,I:pInput=dts_return)";
    trs_modify.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm + ",EMAIL=" + js_email;
    trs_modify.Post();
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);

    //PanelToGroupBox(panel_3);
    //PanelToGroupBox(panel_4);

    ins_combo_set(dts_SPOT_ISU_TRD_MKT_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "01213"); // 01213 - 현물종목거래시장구분코드
    ins_combo_set(dts_TRANSSTK_AGNT_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "00685"); // 00685 - 명의개서회사
    ins_combo_set(dts_COM_ATTR_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "00840"); // 00840 - 회사속성구분코드
    ins_combo_set(dts_LIST_STAT_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "00714"); // 00714 - 시장구분 

    $c.stf.showObj(txb_simbol_chk, false);
    $c.stf.showObj(txb_ISUR_APPL_ID, false);
    $c.stf.showObj(txb_IMSI_ISUR_CD, false);
    $c.stf.showObj(txb_param1, false);
    $c.stf.showObj(txb_param2, false);
    $c.stf.showObj(txb_param3, false);
    //showObj(btn_simbol,false);

    //2016.09.19 표준코드 ID 생성으로 인한 필요없는 항목 삭제----------------------------------
    //showObj(panel_4,false); 
    $c.stf.showObj(txb_APCT_BELNG_COM_NM, false);
    $c.stf.showObj(txb_APCT_NM, false);
    $c.stf.showObj(txb_APCT_TEL_NO, false);
    $c.stf.showObj(txb_APCT_INNR_NO, false);
    $c.stf.showObj(txb_ENCRYP_APCT_EMAIL, false);
    $c.stf.showObj(txb_APCT_FAX_NO, false);
    $c.stf.showObj(txb_CORP_USR_REG_APPL_SEQ, false);
    //2016.09.19 표준코드 ID 생성으로 인한 필요없는 항목 삭제----------------------------------

    scwin.ins_search();
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	
    fn_RowPos(dts_List, 1);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
