scwin.dts_Simbol_OnLoadCompleted = function(rowcount) {
    if (rowcount == 0) {
        $c.win.alert(" 사용할 수 있습니다. [ 심볼 중복 체크 ]");
        txb_simbol_chk.setValue("Y");
    } else {
        $c.win.alert(" 이미 사용 중 입니다.  [ 심볼 중복 체크 ]");
        txb_simbol_chk.setValue("F");
    }
};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    var ISUR_APPL_ID = dts_List.getCellData(row, "ISUR_APPL_ID");
    txb_simbol_chk.setValue("N");
    scwin.V_ISUR_APPL_ID = ISUR_APPL_ID;
    scwin.ins_detail();
};
scwin.dts_Rst_OnLoadCompleted = function(rowcount) {
    // 발행기관 등록후 결과값을 받아 처리한다.
    var RESULT_CONTN = dts_Rst.getCellData(0, "RESULT_CONTN");
    //alert(RESULT_CONTN); 
    if (RESULT_CONTN == "SPECLBND_ISUR_CD") {
        $c.win.alert(" 동일한 특수채 기관코드가 존재합니다.[" + txb_SPECLBND_ISUR_CD.getValue() + "]\n " + txb_COM_NM.getValue());
    } else if (RESULT_CONTN == "BENFCERT_ISUR_CD") {
        $c.win.alert(" 동일한 수익증권 기관코드가 존재합니다.[" + txb_BENFCERT_ISUR_CD.getValue() + "]\n " + txb_COM_NM.getValue());
    } else if (RESULT_CONTN == "NEW_ISUR_CD_FAIL") {
        $c.win.alert(" 발행기관 코드 생성시 실패입니다.\n 다시 시도 부탁드립니다.");
    } else if (RESULT_CONTN == "NEW_ISUR_CD") {
        $c.win.alert(" 발행기관코드 중복 체크\n 발행기관코드가 존재합니다.");
    } else if (RESULT_CONTN == "NEW_ISUR_CD_TEMP_FAIL") {
        $c.win.alert(" 임시발행기관코드 입니다. ");
    } else if (RESULT_CONTN == "NEW_ISUR_CD_5_FAIL") {
        $c.win.alert(" 발행기관 코드 생성시 실패입니다.\n발행기관코드는 5자리 입니다.\n다시 시도 부탁드립니다.");
    } else {
        $c.win.alert(txb_COM_NM.getValue() + "\n[" + RESULT_CONTN + "] 발행기관 코드 생성되었습니다.");
        //	 ins_search();
        scwin.V_ISUR_APPL_ID = RESULT_CONTN;
        scwin.ins_detail(); // 신청 데이터 불러오기 ( 재조회 )
        scwin.ins_search();
    }
};
scwin.dts_Rst2_OnLoadCompleted = function(rowcount) {
    // 발행기관  반송처리 결과값을 받아 처리한다.
    var RESULT_CONTN = dts_Rst.getCellData(0, "RESULT_CONTN");
    //alert(RESULT_CONTN);  
    $c.win.alert(txb_COM_NM.getValue() + "\n[" + txb_ISUR_CD.value + "] 발행기관 반송처리 완료 .");
    //	 ins_search();
    scwin.V_ISUR_APPL_ID = "";
    scwin.ins_detail();
    scwin.ins_search();
};
