    if (txb_ISUR_SYMBL.getValue() == "" || txb_ISUR_SYMBL.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "회사심볼"));
        txb_ISUR_SYMBL.focus();
        return;
    }
    scwin.readCorpInfoSimbol();
};
